insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('off_by_one', 1, 'passo_a_passo', 'Confira contando', '["Sua resposta ficou perto — confira: conte nos dedos ou numa reta numérica e verifique se não parou um passo antes ou depois."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('forgot_carry', 1, 'passo_a_passo', 'Quando a coluna passa de 9', '["Some a coluna da direita (unidades). Se der 10 ou mais, escreva só o dígito das unidades e leve o dez para a coluna seguinte.","Na próxima coluna, some também o que veio \"de carona\"."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('forgot_carry', 2, 'visual', 'Caixas de 10', '["Imagine 10 cubinhos soltos: eles formam uma barra de 10. Ao passar de 9 unidades, troque 10 cubinhos por 1 barra e coloque a barra na coluna das dezenas."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('swap_operands', 1, 'passo_a_passo', 'Ordem importa na subtração', '["Em 12 − 5, você começa em 12 e tira 5. Não dá para \"tirar 12 de 5\". Escreva sempre o maior primeiro e confira com a soma: 7 + 5 = 12."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('swap_operands', 2, 'historia', 'História das figurinhas', '["Você tem 12 figurinhas e dá 5. Quantas restam? Contar o que sobra mostra que o resultado é 7, não −7."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('smaller_from_larger', 1, 'passo_a_passo', 'Quando falta na coluna', '["Se o número de cima é menor que o de baixo, peça 1 dezena emprestada à coluna vizinha: ela vira 10 unidades. Ex.: 52 − 27: 12 − 7 = 5; depois 4 − 2 = 2 → 25."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('smaller_from_larger', 2, 'visual', 'Trocar uma barra por 10 cubinhos', '["52 = 5 barras e 2 cubinhos. Para tirar 7 cubinhos, desmonte 1 barra em 10 cubinhos: agora são 4 barras e 12 cubinhos."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('borrow_slip', 1, 'passo_a_passo', 'Conferir com a soma', '["Depois de subtrair, some o resultado ao número de baixo: deve voltar ao número de cima. Se não voltar, revise o empréstimo."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_instead_of_multiply', 1, 'visual', 'Grupos iguais', '["4 × 3 significa 4 grupos de 3: 3 + 3 + 3 + 3 = 12. Desenhe os grupos e conte."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_instead_of_multiply', 2, 'passo_a_passo', 'Multiplicar é somar parcelas iguais', '["Reescreva a multiplicação como soma repetida e some. Depois memorize os resultados na tabuada."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('table_slip', 1, 'passo_a_passo', 'Apoie-se em um produto que você sabe', '["7 × 6: se 7 × 5 = 35, então 7 × 6 = 35 + 7 = 42."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('forgot_carry_mul', 1, 'passo_a_passo', 'Levar também na multiplicação', '["26 × 3: 6 × 3 = 18 → escreva 8 e leve 1; 2 × 3 = 6, mais 1 que veio = 7 → 78."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('forgot_shift_zero', 1, 'passo_a_passo', 'O zero que "desliza"', '["Ao multiplicar pelas dezenas, a linha começa com um zero (ou uma casa vazia): você está multiplicando por 10, 20, 30… Só depois some as linhas."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('divide_wrong_operation', 1, 'historia', 'Repartir em partes iguais', '["24 balas para 6 amigos: cada um recebe quantas? Pense \"6 vezes quanto dá 24?\" → 4. Dividir é o inverso de multiplicar."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('divide_wrong_operation', 2, 'passo_a_passo', 'Use a tabuada ao contrário', '["Para 24 ÷ 6, procure na tabuada do 6 o número que chega a 24."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('ignore_remainder', 1, 'passo_a_passo', 'O que sobra também conta', '["47 ÷ 5: cabem 9 grupos de 5 (45) e sobram 2. Escrevemos \"9 resto 2\". Confira: 9 × 5 + 2 = 47."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('remainder_too_big', 1, 'passo_a_passo', 'O resto é menor que o divisor', '["Se o resto é igual ou maior que o divisor, ainda dá para formar mais um grupo. Tente de novo com um quociente maior."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('multiple_divisor_confusion', 1, 'contraexemplo', 'Divisor × múltiplo', '["Divisores \"cabem dentro\" do número (6 divide 12). Múltiplos \"vão além\" (24 é múltiplo de 12). Faça a pergunta: o número divide os dois, sem sobrar?"]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('not_greatest', 1, 'passo_a_passo', 'Liste todos os divisores', '["Escreva os divisores de cada número, marque os comuns e escolha o maior."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('swap_num_den', 1, 'visual', 'Quem é quem', '["O denominador (embaixo) diz em quantas partes iguais o todo foi dividido. O numerador (em cima) diz quantas partes estamos considerando. 3 de 8 partes → 3/8."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('swap_num_den', 2, 'historia', 'A pizza', '["A pizza tem 8 fatias (embaixo). Você comeu 3 (em cima). Lemos \"três oitavos\"."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('count_unshaded', 1, 'visual', 'Conte o que está pintado', '["A fração representa as partes destacadas (pintadas). As não pintadas representam a fração complementar."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('part_to_part', 1, 'visual', 'Sempre compare com o todo', '["O denominador é o total de partes iguais — pintadas e não pintadas juntas."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('bigger_denominator_bigger', 1, 'visual', 'Pizzas do mesmo tamanho', '["Divida duas pizzas iguais: uma em 3 fatias, outra em 5. As fatias de 1/3 são maiores que as de 1/5. Quanto mais partes, menores elas são."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('bigger_denominator_bigger', 2, 'contraexemplo', 'Teste com 1/2 e 1/10', '["Prefere 1/2 ou 1/10 de chocolate? Mesmo \"10 > 2\", 1/2 é muito mais."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('compare_numerators_only', 1, 'passo_a_passo', 'Mesmo tamanho de parte primeiro', '["Para comparar, deixe as frações com o mesmo denominador (partes do mesmo tamanho). Depois compare os numeradores."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_same_to_both', 1, 'visual', 'Equivalência é multiplicar (ou dividir) os dois termos', '["1/2 → 2/4 → 3/6: o denominador dobra, triplica, e o numerador acompanha. Somar o mesmo valor muda o tamanho da fração."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_same_to_both', 2, 'contraexemplo', 'Teste: 1/2 e 2/3', '["Se somar 1 em cima e embaixo valesse, 1/2 = 2/3. Mas 1/2 é metade e 2/3 é mais que a metade."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('multiply_num_only', 1, 'passo_a_passo', 'Os dois termos juntos', '["Para manter o valor, multiplique numerador e denominador pelo mesmo número."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('divide_only_numerator', 1, 'passo_a_passo', 'Dividir em cima e embaixo', '["Simplificar é dividir numerador e denominador pelo mesmo número: 6/8 ÷ 2 = 3/4."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('subtract_to_simplify', 1, 'contraexemplo', 'Subtrair muda o valor', '["6/8 − 2 em cima e embaixo daria 4/6, que não é a mesma quantidade. Divisão mantém o valor."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('partial_simplify', 1, 'passo_a_passo', 'Continue até não dar mais', '["Depois de simplificar, veja se ainda há divisor comum. 12/18 → 6/9 → 2/3."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_denominators', 1, 'visual', 'Fatias do mesmo tamanho', '["1/5 + 2/5: são fatias de quinto. Juntar 1 fatia e 2 fatias dá 3 fatias de quinto = 3/5. O tamanho da fatia (denominador) não muda."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_denominators', 2, 'historia', 'Barra de chocolate', '["Uma barra em 5 pedaços: você come 1 e depois mais 2. Comeu 3 pedaços de 5."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_num_and_den', 1, 'visual', 'Fatias de tamanhos diferentes', '["1/2 e 1/3 são fatias de tamanhos diferentes e não dá para somá-las direto. Troque ambas por sextos: 3/6 + 2/6 = 5/6."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_num_and_den', 2, 'contraexemplo', 'Teste simples', '["Se 1/2 + 1/3 fosse 2/5, a soma seria menor que 1/2 (2/5 = 0,4), mas juntar mais um pedaço não pode diminuir a quantidade."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('add_num_and_den', 3, 'passo_a_passo', 'Receita', '["1) ache um denominador comum; 2) converta cada fração; 3) some os numeradores; 4) mantenha o denominador; 5) simplifique."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('common_den_not_converted', 1, 'passo_a_passo', 'Converter também o numerador', '["1/2 = 3/6 (multiplicou por 3 em cima e embaixo). Só depois some os numeradores."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('wrong_operation', 1, 'historia', 'Qual é a história?', '["Juntar → somar. Tirar/comparar → subtrair. Grupos iguais → multiplicar. Repartir igualmente → dividir. Conte a história com suas palavras antes de escolher a conta."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('keyword_trap', 1, 'contraexemplo', 'Palavra-pista pode enganar', '["\"4 a mais que João\" não significa somar a 4 se já sabemos quanto tem o outro. Desenhe quem tem mais e quem tem menos."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('one_step_only', 1, 'passo_a_passo', 'Releia a pergunta', '["Sublinhe o que a pergunta final pede. Se ainda faltam informações, há outra etapa."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('wrong_order', 1, 'passo_a_passo', 'Siga a história na ordem', '["Escreva cada acontecimento como uma conta, na ordem em que acontece."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('fraction_of_quantity_error', 1, 'passo_a_passo', '1/4 de 20', '["O denominador diz em quantas partes dividir (20 ÷ 4 = 5). O numerador diz quantas dessas partes pegar (1 × 5 = 5)."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('perc_number_confusion', 1, 'passo_a_passo', 'Porcentagem é "por cem"', '["15% significa 15 em cada 100, ou seja, 15/100. Para achar 15% de 400: 400 ÷ 100 = 4 (isso é 1%) e 4 × 15 = 60."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('perc_number_confusion', 2, 'visual', 'Barra de 100 partes', '["Imagine o valor numa barra dividida em 100 partes iguais. 15% é pintar 15 dessas partes. Cada parte vale 400 ÷ 100 = 4, então são 15 × 4 = 60."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('perc_wrong_operation', 1, 'passo_a_passo', 'Divida por 100 (ou use frações)', '["p% de V = V × p ÷ 100. Atalhos: 10% é V ÷ 10; 50% é metade; 25% é a metade da metade."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('adjust_value_as_price', 1, 'passo_a_passo', 'Duas etapas', '["1) Ache quanto é o desconto (ou acréscimo): p% do preço. 2) Tire (ou some) do preço original. A pergunta pede o preço FINAL, não só o valor do desconto."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('adjust_value_as_price', 2, 'historia', 'Na loja', '["Se um tênis de R$ 200 tem 25% de desconto, você economiza R$ 50 (isso é o desconto). Mas o que sai do seu bolso é 200 − 50 = R$ 150."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('adjust_wrong_direction', 1, 'contraexemplo', 'Desconto diminui, acréscimo aumenta', '["Antes de calcular, estime: com desconto o preço final tem que ficar MENOR que o original; com acréscimo, MAIOR. Se o seu resultado contraria isso, revise a operação."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('percent_applied_as_number', 1, 'contraexemplo', '25% não é 25 reais', '["Se o preço fosse R$ 40, 25% seria R$ 10; se fosse R$ 400, seria R$ 100. A porcentagem depende do valor! Primeiro ache p% do preço, depois aplique."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('percent_applied_as_number', 2, 'passo_a_passo', 'Fator multiplicador', '["Desconto de 25% = pagar 75% do preço: preço × 0,75. Acréscimo de 10% = pagar 110%: preço × 1,10."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('additive_proportion', 1, 'contraexemplo', 'Proporção multiplica', '["Se 3 canetas custam R$ 12, 5 canetas não custam 12 + 2. Descubra o preço de UMA (12 ÷ 3 = 4) e multiplique pela quantidade (4 × 5 = 20)."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('additive_proportion', 2, 'visual', 'Tabela', '["Monte uma tabela: 3 → 12, 1 → 4, 5 → 20. Ao passar de 3 para 1 você dividiu por 3; de 1 para 5, multiplicou por 5. O preço acompanha."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('prop_multiply_all', 1, 'passo_a_passo', 'Monte a regra de três', '["Coloque as grandezas em colunas: quantidade e preço. Ache o valor de 1 unidade e depois multiplique. Não multiplique tudo de uma vez."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('ratio_part_of_part', 1, 'passo_a_passo', 'Some as partes primeiro', '["Razão 2:3 → 2 + 3 = 5 partes iguais. Cada parte vale total ÷ 5. A maior parte são 3 dessas partes."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('ratio_part_of_part', 2, 'visual', 'Barra em partes', '["Desenhe uma barra com 5 quadradinhos iguais: 2 para um lado, 3 para o outro. O total é dividido em 5, não em 3."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('forgot_divide_coef', 1, 'passo_a_passo', 'Duas operações inversas', '["Em 3x + 5 = 20: tire 5 dos dois lados (3x = 15) e depois divida os dois lados por 3 (x = 5). O 3 está multiplicando x, então ele ainda precisa sair."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('eq_sign_error', 1, 'passo_a_passo', 'Inverta a operação ao trocar de lado', '["O que está somando passa subtraindo, e o que está subtraindo passa somando. Confira sempre substituindo o valor na equação original."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('eq_sign_error', 2, 'visual', 'Balança', '["Uma equação é uma balança em equilíbrio. O que você faz de um lado (tirar 5) precisa fazer do outro."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('mean_sum_only', 1, 'passo_a_passo', 'Média = soma ÷ quantidade', '["Some todos os valores e divida pela quantidade de valores. A soma sozinha mostra o total, não o \"valor típico\"."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('mean_sum_only', 2, 'historia', 'Repartir igual', '["A média é quanto cada um receberia se o total fosse repartido igualmente entre todos."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('mean_as_middle', 1, 'contraexemplo', 'Os extremos não bastam', '["Em 2, 2, 2, 10 a média é 4, mas (2 + 10) ÷ 2 = 6. A média usa TODOS os valores: some todos e divida pela quantidade."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('interest_ignores_time', 1, 'passo_a_passo', 'Juros dependem do tempo', '["Juros simples = capital × taxa × tempo. Com 2% ao mês por 3 meses, são 3 vezes os juros de um mês."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('interest_vs_total', 1, 'passo_a_passo', 'Juros ≠ montante', '["Juros é só o acréscimo. Montante (total) = capital + juros. Releia o que a pergunta pede."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_literal_skim', 1, 'passo_a_passo', 'Volte ao texto', '["Procure a frase que responde à pergunta e sublinhe-a antes de escolher a alternativa."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_over_infer', 1, 'passo_a_passo', 'Do texto, não do palpite', '["Uma inferência precisa de pelo menos uma pista no texto. Qual frase apoia sua resposta?"]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_agree_noun', 1, 'passo_a_passo', 'Combine artigo, substantivo e adjetivo', '["Se o substantivo está no feminino plural, os acompanhantes também: \"as casas pequenas\"."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('count_off_by_one', 1, 'passo_a_passo', 'Toque e conte', '["Encoste o dedo em cada objeto, uma vez só, e diga um número para cada toque. O último número que você falou é a quantidade."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('compare_wrong_direction', 1, 'historia', 'Duas pilhas de bolinhas', '["Maior é a pilha que tem mais bolinhas; menor é a que tem menos. Leia de novo a pergunta: ela pede o maior ou o menor?"]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('order_neighbor_confusion', 1, 'passo_a_passo', 'Caminhe na fila dos números', '["Depois é um passo para frente (7 → 8). Antes é um passo para trás (7 → 6)."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('shape_square_rect', 1, 'visual', 'Quadrado tem lados iguais', '["O quadrado tem 4 lados do mesmo tamanho. O retângulo também tem 4 lados, mas dois são mais compridos que os outros dois."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('shape_sides_count', 1, 'passo_a_passo', 'Marque o começo', '["Comece num canto, passe o dedo lado por lado e pare quando voltar ao canto do começo."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pattern_repeat_last', 1, 'passo_a_passo', 'Ache o pedacinho que se repete', '["Em azul, vermelho, azul, vermelho, a unidade é \"azul, vermelho\". Depois do vermelho vem o azul de novo, não outro vermelho."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pattern_wrong_step', 1, 'passo_a_passo', 'Veja o tamanho do pulo', '["2, 4, 6, 8: de um número para o outro sobe 2. Continue pulando 2: 10."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('time_base_ten', 1, 'contraexemplo', 'O relógio conta de 60 em 60', '["1 hora tem 60 minutos, não 100. Por isso meia hora são 30 minutos e 2 horas e meia são 150 minutos."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('time_hour_carry', 1, 'passo_a_passo', 'Passou de 60? Vira hora', '["Some os minutos. Se der 60 ou mais, tire 60 e some 1 hora. 50 + 40 = 90 min = 1h30."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('money_add_instead', 1, 'historia', 'A história do dinheiro', '["Pagou e recebeu de volta? Então o troco é o que sobra: tire o preço do valor pago. Se está juntando preços, aí sim soma."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('money_subtract_instead', 1, 'passo_a_passo', 'Juntar é somar', '["Para saber quanto custa tudo junto, some os preços."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('money_forgot_step', 1, 'passo_a_passo', 'Duas etapas', '["1) Ache o total gasto. 2) Tire o total do dinheiro que você deu: o que sobra é o troco."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('dec_longer_bigger', 1, 'contraexemplo', 'Mais algarismos não é maior', '["0,5 é metade (5 décimos). 0,47 é menos que a metade. Escreva 0,5 como 0,50 e compare 50 com 47."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('dec_separate_parts', 1, 'passo_a_passo', 'Alinhe a vírgula', '["2,7 + 1,5: some os décimos (7 + 5 = 12 → escreva 2 e leve 1 para a unidade) e depois os inteiros (2 + 1 + 1 = 4). Resultado 4,2."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('dec_align_digits', 1, 'passo_a_passo', 'Vírgula embaixo de vírgula', '["Complete com zeros: 2,50 + 1,75. Alinhe as vírgulas e some coluna por coluna."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('neg_bigger_digit', 1, 'visual', 'A reta dos números', '["Na reta, o que fica mais à direita é maior. −3 está à direita de −7, então −3 > −7."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('neg_sign_drop', 1, 'passo_a_passo', 'Passou do zero, é negativo', '["Se a temperatura cai mais do que o valor que tinha, o resultado fica abaixo de zero e leva o sinal de menos."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('neg_add_instead', 1, 'historia', 'O termômetro', '["Cair é descer no termômetro: é subtrair. Subir é somar. Imagine o termômetro antes de calcular."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('perim_area_confusion', 1, 'visual', 'Perímetro é a cerca', '["Perímetro é a volta da figura (como uma cerca): soma de todos os lados. Área é o que cabe dentro (quadradinhos)."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('perim_two_sides_only', 1, 'passo_a_passo', 'Contorne tudo', '["Um retângulo tem 4 lados. Some os 4 (ou dobre a soma de dois lados vizinhos)."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('area_perim_confusion', 1, 'visual', 'Área é o piso', '["Área é quantos quadradinhos cobrem a figura por dentro: comprimento × largura. A soma dos lados mede o contorno."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('area_add_sides', 1, 'contraexemplo', 'Some e multiplique não são iguais', '["Retângulo 4 por 3: tem 12 quadradinhos (4 × 3). A soma dos lados (4 + 3 = 7) não conta os quadradinhos."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('tri_area_forgot_half', 1, 'visual', 'Triângulo = metade do retângulo', '["Dois triângulos iguais formam um retângulo. Então a área do triângulo é base × altura ÷ 2."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_letter_sound_confuse', 1, 'passo_a_passo', 'Escute e olhe a boca', '["Fale devagar: B e P usam os lábios; F e V usam dentes e lábio. Escute se o som vibra ou não."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_syl_count_letters', 1, 'passo_a_passo', 'Bata palmas', '["Cada palma é uma sílaba: sa-pa-to tem 3 palmas, mesmo tendo 6 letras."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_rhyme_first_letter', 1, 'passo_a_passo', 'Rima é o final', '["Palavras que rimam terminam igual: gato e pato (…ato). Começar igual não é rima."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_rhyme_meaning', 1, 'passo_a_passo', 'Rima é som, não assunto', '["Bola e chute são do mesmo assunto, mas só bola e cola rimam: terminam com o mesmo som."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_tense_confuse', 1, 'historia', 'A linha do tempo', '["Passado: já aconteceu (brinquei). Presente: está acontecendo (brinco). Futuro: ainda vai acontecer (brincarei). Veja o fim do verbo."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_punct_period_always', 1, 'passo_a_passo', 'Cada frase tem seu sinal', '["Pergunta termina em ? , afirmação termina em . e surpresa ou emoção termina em !."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_comma_before_e', 1, 'passo_a_passo', 'Antes do "e", sem vírgula', '["Na lista, a vírgula separa os itens e o \"e\" já faz a ligação final: \"maçã, pera e uva\"."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_comma_none', 1, 'passo_a_passo', 'Separe os itens', '["Quando há uma lista, use vírgula entre os itens para a leitura ficar clara."]'::jsonb);
insert into app.misconception_explanations(misconception_id, variant, method, title, body) values ('pt_synonym_antonym', 1, 'passo_a_passo', 'Parecido ou contrário?', '["Sinônimo é palavra de significado parecido (grande → enorme). Antônimo é o contrário (grande → pequeno). Releia o que a pergunta pede."]'::jsonb);
